{
  "description": "The creature is a quadrupedal mammal with the overall body, fur, head and limbs of a brown bear, but with insect-like features integrated into its back and forehead. It stands in profile facing right, covered in thick shaggy brown fur that is lighter tan on the muzzle and chest and darker on the lower legs. A large, glossy, dark reddish-brown to black segmented exoskeleton covers the entire dorsal side from the shoulders to the rump, and a single large curved, notched horn rises from the forehead. The animal has a bear-like snout, small rounded ears, four clawed paws, and a very short tail, with a row of oval openings visible on the fur just below the edge of the shell.",
  "parts": [
    {
      "part": "head",
      "looks_like": "a brown bear head with dense brown fur, a lighter tan muzzle, a large black nose at the tip of the snout, small dark brown eyes on the sides, and a closed mouth with a slightly lighter lower lip",
      "where": "at the front of the body, attached to the neck"
    },
    {
      "part": "horns",
      "looks_like": "one large glossy dark brown to black horn curving up and forward from the forehead, with several pointed notches along the inner curve and a forked tip, plus a tiny sharp point at the base just in front of the main horn",
      "where": "on the top of the forehead between the ears"
    },
    {
      "part": "ears",
      "looks_like": "two small rounded ears covered in thick brown fur, with soft rounded tips",
      "where": "on top of the head behind the horn, one on each side"
    },
    {
      "part": "legs",
      "looks_like": "four thick, heavily furred brown bear legs with long shaggy fur, two forelegs under the chest and two hind legs under the hips",
      "where": "under the body, supporting it from below"
    },
    {
      "part": "feet",
      "looks_like": "four large broad paws with dark pads and five long curved light-colored claws on each, the fur extends down to the paws",
      "where": "at the bottom ends of each leg touching the ground"
    },
    {
      "part": "tail",
      "looks_like": "a very short, small rounded tuft of brown fur, barely protruding",
      "where": "at the rear of the body above the hind legs, partially covered by the rear edge of the shell"
    },
    {
      "part": "shell",
      "looks_like": "a large glossy exoskeleton in dark reddish-brown to black, with a smooth domed shield over the shoulders and a longer segmented section over the back, shiny and hard-looking",
      "where": "covering the entire back from just behind the neck to just above the tail"
    },
    {
      "part": "plates",
      "looks_like": "overlapping transverse ridged plates forming the shell, with about 12-13 visible segments on the back portion and a larger smooth pronotal plate over the shoulders, with small oval holes along the lower edge of the plates where they meet the fur",
      "where": "making up the shell on the dorsal side, arranged in a row from shoulders to rump"
    },
    {
      "part": "markings",
      "looks_like": "a row of seven oval dark-rimmed openings with light centers on the fur, resembling spiracles, plus lighter tan fur on the muzzle and lower chest contrasting with darker brown fur on the legs and back",
      "where": "the oval openings are in a horizontal line on the brown fur of the flank just below the lower edge of the shell; the color variation is on the head and torso"
    }
  ],
  "attached_objects": [],
  "animals": [
    "bear",
    "beetle"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
